import{_ as r,o,c as t,ag as a}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"🔬 科学快报 | 2026年8月8日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-08.md","filePath":"science-log/src/reconstructed/2026-08-08.md"}'),n={name:"science-log/src/reconstructed/2026-08-08.md"};function s(i,e,u,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="🔬-科学快报-2026年8月8日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月8日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月8日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月8日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日为周六（2026-08-08），Nature / Science / PNAS 均无研究论文刊出（CrossRef 命中：Nature 0、PNAS 0、Science 仅 1 条政策新闻），故科学 5 篇取自最近的出版窗口 <strong>2026-08-04 ~ 2026-08-08</strong>，并逐条标注实际出版日。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608080000 TO 202608082359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🌪️-用-ai-做业务化热带气旋预报-路径、强度、风圈半径全面领先一天" tabindex="-1">🌪️ 用 AI 做业务化热带气旋预报：路径、强度、风圈半径全面领先一天 <a class="header-anchor" href="#🌪️-用-ai-做业务化热带气旋预报-路径、强度、风圈半径全面领先一天" aria-label="Permalink to &quot;🌪️ 用 AI 做业务化热带气旋预报：路径、强度、风圈半径全面领先一天&quot;">​</a></h3><p><strong>Operational tropical cyclone forecasting with AI</strong><em>Nature（2026-08-06）</em></p><p>Google DeepMind 的 WeatherNext Cyclones（WN-C）是一个 AI 业务化预报模型，同时给出路径、强度和风圈半径的集合预报，可外推 15 天、集合规模可达 1000 成员。在 2023–2025 年的热带气旋上评估，其三个目标平均提前量优势达 1 天以上——相当于过去十年业务模式发展的全部进步。关键反直觉结论：它用的是比区域模式粗几个数量级的输入，说明高分辨率并非最先进强度预报的必要前提，粗分辨率大气数据里被低估了强度信号。纳入加权共识集合后，集合技能显著提升；千成员集合对稀有事件的刻画优于常规 50 成员集合。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10953-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10953-2</a></p><h3 id="☀️-甲脒共晶把钙钛矿-硅叠层的热蒸发做到了-200-cm2" tabindex="-1">☀️ 甲脒共晶把钙钛矿/硅叠层的热蒸发做到了 200 cm² <a class="header-anchor" href="#☀️-甲脒共晶把钙钛矿-硅叠层的热蒸发做到了-200-cm2" aria-label="Permalink to &quot;☀️ 甲脒共晶把钙钛矿/硅叠层的热蒸发做到了 200 cm²&quot;">​</a></h3><p><strong>Thermally evaporated perovskite/silicon tandems via formamidinium eutectic</strong><em>Nature（2026-08-05）</em></p><p>溶液法做出了高效钙钛矿/硅叠层电池，却难以兼顾工业可扩展性与长期可靠性；热蒸发更工业友好，但一直没能在 大面积叠层上成功，卡点是高温蒸发时甲脒碘（FAI）热分解。作者合成了一种甲脒基共晶，把 FAI 的有效蒸发温度平均压低 36 °C，落到分解阈值之下，从而在不分解的前提下稳定蒸发，膜结晶性与原子级成分均匀性同时改善。1 cm² 器件稳态效率 31.5%；在商用半片 G12 硅片上做到 200 cm²、稳态效率 30%，面积放大 200 倍的相对效率损失仅 3.99%，为钙钛矿叠层中已报道的最低面积放大损失。85 °C/85% RH 湿热老化 2000 h 后保持 95% 初始效率，户外实测两个月功率损失可忽略。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10970-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10970-1</a></p><h3 id="🌌-射电磁星的偏振-x-射线-真空双折射的首个天体证据" tabindex="-1">🌌 射电磁星的偏振 X 射线：真空双折射的首个天体证据 <a class="header-anchor" href="#🌌-射电磁星的偏振-x-射线-真空双折射的首个天体证据" aria-label="Permalink to &quot;🌌 射电磁星的偏振 X 射线：真空双折射的首个天体证据&quot;">​</a></h3><p><strong>Vacuum birefringence and the polarized X-ray emission from a radio magnetar</strong><em>Nature（2026-08-05）</em></p><p>磁星表面磁场超过 10¹⁴ G，其 X 射线辐射正好探测量子电动力学（QED）介入光传播的 regime——强磁场使真空出现偏振相关的折射率，即&quot;真空双折射&quot;，这是 QED 长期未被证实的标志性预言。作者协调 IXPE、NICER 与 Parkes/Murriyang 对射电发射磁星 1E 1547.0-5408 做相位与能量分辨的偏振测量：热主导的软 X 射线带偏振度很高，2 keV 处相位平均达 65%，在 2–4 keV 间大幅下降；某些自转相位上 2–3 keV 偏振度接近 80%，穿越射电束期间仍保持 ≳40%。X 射线与射电偏振角均符合旋转矢量模型，说明辐射几何跟随大尺度磁场；而标准&quot;光非折射传播到无穷远&quot;的表面发射模型无法解释，只有真空双折射主导的磁层传播能自然给出这些信号。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10859-z" target="_blank" rel="noreferrer">10.1038/s41586-026-10859-z</a></p><h3 id="⚛️-双轨擦除量子比特的纠缠门-把错误层级保住" tabindex="-1">⚛️ 双轨擦除量子比特的纠缠门：把错误层级保住 <a class="header-anchor" href="#⚛️-双轨擦除量子比特的纠缠门-把错误层级保住" aria-label="Permalink to &quot;⚛️ 双轨擦除量子比特的纠缠门：把错误层级保住&quot;">​</a></h3><p><strong>An entangling gate for dual-rail erasure qubits</strong><em>Nature（2026-08-05）</em></p><p>量子纠错的硬件开销与物理门错误率是两大瓶颈，而&quot;擦除量子比特&quot;通过制造强错误层级来缓解：可探测的泄漏错误远多于残余 Pauli 错误，于是阈值更高、随码距缩放更好。但前提是这道层级必须在所有门操作中尽量不被破坏。D-Wave Quantum 团队设计并实现了双轨腔量子比特（编码在一对超导微波腔内）的两比特纠缠门：门时长约 500 ns，单门擦除率约 0.5%，残余 Pauli 错误低于 0.1%，且强烈偏向退相位——比特翻转在 10⁻⁶ 量级几乎不存在。配合表面码模拟，作者论证这是通往&quot;随规模快速压制错误&quot;的纠错系统的一条更快路径。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10822-y" target="_blank" rel="noreferrer">10.1038/s41586-026-10822-y</a></p><h3 id="🧠-杏仁核星形胶质细胞的初级纤毛参与应激行为" tabindex="-1">🧠 杏仁核星形胶质细胞的初级纤毛参与应激行为 <a class="header-anchor" href="#🧠-杏仁核星形胶质细胞的初级纤毛参与应激行为" aria-label="Permalink to &quot;🧠 杏仁核星形胶质细胞的初级纤毛参与应激行为&quot;">​</a></h3><p><strong>Amygdala astrocyte primary cilium mechanisms contribute to stress behaviours</strong><em>Nature（2026-08-05）</em></p><p>逆境如何触发应激相关行为改变仍未解。作者把目光放到杏仁核的星形胶质细胞及其初级纤毛（一种以 GPCR 信号为核心的细胞器）：应激后杏仁核星形胶质细胞在蛋白与基因表达层面发生改变，初级纤毛相关分子表达下降、纤毛形态变短。用化学遗传学激活或直接靶向天然 1-磷酸鞘氨醇受体 1（S1PR1），可恢复纤毛长度、纠正分子改变并改善应激相关行为。人杏仁核星形胶质细胞同样高表达纤毛相关基因与 S1PR1，且在应激相关脑病中多有表达紊乱；在小鼠中选择性遗传破坏杏仁核星形胶质细胞初级纤毛，会改变部分应激行为与胶质/实质细胞的基因表达。这把&quot;细胞器级别的胶质信号&quot;接入了情绪障碍的机制链条。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10874-0" target="_blank" rel="noreferrer">10.1038/s41586-026-10874-0</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🐍-ouroboros-一次-被审阅的自我进化-把编码智能体练到-terminal-bench-2-1-榜首" tabindex="-1">🐍 Ouroboros：一次&quot;被审阅的自我进化&quot;，把编码智能体练到 Terminal-Bench 2.1 榜首 <a class="header-anchor" href="#🐍-ouroboros-一次-被审阅的自我进化-把编码智能体练到-terminal-bench-2-1-榜首" aria-label="Permalink to &quot;🐍 Ouroboros：一次&quot;被审阅的自我进化&quot;，把编码智能体练到 Terminal-Bench 2.1 榜首&quot;">​</a></h3><p><strong>Ouroboros: A Self-Developing Frontier Coding Agent with Reviewed Core Evolution</strong><em>arXiv:2608.08311（2026-08-08）</em></p><p>作者提出的 Ouroboros 是一个&quot;自发展&quot;的智能体框架（harness）：工具、提示、上下文组装乃至核心实现都通过<strong>被审阅的提交</strong>改进，而这些提交又成为后续工作的运行时。核心进化有两模式——&quot;递归自由进化&quot;（把改进本身当作任务，完成一轮可调度下一轮）与&quot;经验驱动核心进化&quot;（日常工作与社交交互暴露出 bug、粗糙边缘与低效的上下文构造，触发结构改动）。成绩：Terminal-Bench 2.1 上 Opus 5 跑出 86.74%（该基准已报告最好结果），OSWorld-Verified 达 90.69%（超过此前最好），五轮 CL-Bench 归一化奖励 0.2301 创 SOTA。作者同时给出一个 161 天、跨七个界面的真实部署（Hope）作为长期实验，并强调自改代码 + 自选模型 API 使&quot;护栏在进化与公众压力下仍须具权威性&quot;成为一等设计问题。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.08311" target="_blank" rel="noreferrer">2608.08311</a></p><h3 id="🪝-只靠提问就能下毒-自进化技能的轨迹后门攻击" tabindex="-1">🪝 只靠提问就能下毒：自进化技能的轨迹后门攻击 <a class="header-anchor" href="#🪝-只靠提问就能下毒-自进化技能的轨迹后门攻击" aria-label="Permalink to &quot;🪝 只靠提问就能下毒：自进化技能的轨迹后门攻击&quot;">​</a></h3><p><strong>Query-Only Backdoor Attacks on Self-Evolving Skills via Trajectory Poisoning</strong><em>arXiv:2608.08303（2026-08-08）</em></p><p>自进化技能系统从执行轨迹里自动构建/更新技能，把技能来源从外部市场搬到&quot;可信&quot;的内部进化管线，本来是为了防&quot;技能注入&quot;。作者指出这反而开出新攻击面：攻击者可以间接操控进化过程。他们提出轨迹后门攻击（TBA）——<strong>仅凭查询</strong>，构造让智能体执行目标动作、并在轨迹里明示激活条件的提问；在不同触发任务上重复同一&quot;条件—动作&quot;模式而保持干净查询不变，诱导进化器把该模式固化成&quot;依赖触发器的可复用规则&quot;写进演化出的技能里。这揭示了一个结构性风险：把技能获取内部化只清除了&quot;直接篡改&quot;这一条路，却把信任押在了&quot;轨迹不可被诱导&quot;这个更弱的假设上。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.08303" target="_blank" rel="noreferrer">2608.08303</a></p><h3 id="🧠-把记忆按领域切开-结构化呈现就能同时治-跨域泄漏-与-记忆谄媚" tabindex="-1">🧠 把记忆按领域切开：结构化呈现就能同时治&quot;跨域泄漏&quot;与&quot;记忆谄媚&quot; <a class="header-anchor" href="#🧠-把记忆按领域切开-结构化呈现就能同时治-跨域泄漏-与-记忆谄媚" aria-label="Permalink to &quot;🧠 把记忆按领域切开：结构化呈现就能同时治&quot;跨域泄漏&quot;与&quot;记忆谄媚&quot;&quot;">​</a></h3><p><strong>Mitigating Over-Personalization in LLMs via Structured Memory</strong><em>arXiv:2608.08300（2026-08-08）</em></p><p>长期记忆让助手跨会话个性化，但把用户信息重新塞回上下文时，也会在不相关场景产生不当影响。作者研究两种失败模式：<strong>跨域泄漏</strong>（某一生活领域的记忆影响另一领域的回答）与<strong>记忆诱发谄媚</strong>（存储的用户信念让模型更倾向附和而非说真话）。方法极简：不改模型、不改记忆内容，只在推理期改变&quot;记忆如何呈现&quot;——比较常用的&quot;全量注入为无结构列表&quot;与&quot;按领域分区的结构化格式&quot;。在 PersistBench 上跨 7 个模型，结构化呈现一致降低跨域泄漏且保住实用性，最强方法相对基线平均降低 8.8%。这条结果的价值在于：一个纯格式层面的改动就能缓解一类被归因于&quot;模型人格&quot;的偏差，说明不少过度个性化其实是上下文组织问题。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.08300" target="_blank" rel="noreferrer">2608.08300</a></p><h3 id="🧹-oblivion-技能从注册表删掉不等于消失——工作流级-技能遗忘" tabindex="-1">🧹 OBLIVION：技能从注册表删掉不等于消失——工作流级&quot;技能遗忘&quot; <a class="header-anchor" href="#🧹-oblivion-技能从注册表删掉不等于消失——工作流级-技能遗忘" aria-label="Permalink to &quot;🧹 OBLIVION：技能从注册表删掉不等于消失——工作流级&quot;技能遗忘&quot;&quot;">​</a></h3><p><strong>OBLIVION: Workflow-Level Operational Skill Unlearning for Deployed Agents</strong><em>arXiv:2608.08264（2026-08-08）</em></p><p>当 LLM 智能体成为文件、记忆、注册表与外部工具的操作接口，出现了一个新的&quot;技能吊销&quot;问题：技能从显式注册表移除后，智能体仍可能从档案、对话转录、schema、记忆条目等<strong>残余载体</strong>里把它重建出来。作者把这个问题定义为&quot;操作技能遗忘&quot;——目标不是参数级遗忘，而是阻止已部署智能体通过原语工具重建被吊销的技能。OBLIVION 把每个 episode 建模为 source→sink 工作流，用&quot;跨表面一致擦除&quot;削减残余载体，并在危险 sink 附近做冻结式工作流矫正。在锁定的 88 个攻击 episode 上，无防御臂的攻击成功率是 1.0，OBLIVION 降到 0.114，影响加权暴露降到 0.115，同时锁定效用保持 1.0、良性阻断率 0；在另一技能攻击衍生沙盒上，成功率从 1.0 降到 0.2，暴露从 1.0 降到 0.213，效用控制全保。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.08264" target="_blank" rel="noreferrer">2608.08264</a></p><h3 id="🗄️-superlocalmemory-4-0-一个-受治理-的本地记忆操作系统-以及一个诚实的负结果" tabindex="-1">🗄️ SuperLocalMemory 4.0：一个&quot;受治理&quot;的本地记忆操作系统，以及一个诚实的负结果 <a class="header-anchor" href="#🗄️-superlocalmemory-4-0-一个-受治理-的本地记忆操作系统-以及一个诚实的负结果" aria-label="Permalink to &quot;🗄️ SuperLocalMemory 4.0：一个&quot;受治理&quot;的本地记忆操作系统，以及一个诚实的负结果&quot;">​</a></h3><p><strong>SuperLocalMemory 4.0: The Governed Memory Operating System for AI Agents</strong><em>arXiv:2608.08253（2026-08-08）</em></p><p>这个工作把智能体记忆做成&quot;操作系统&quot;：多通道检索经倒数排名融合统一、双时间维召回、多作用域隔离、基于角色的访问、可验证擦除、哈希链审计轨。主写路径上有一条可靠性脊梁：世代栅栏准入、带逐投影 apply/verify/compensate/erase 归属者的可验证记忆事务、可哈希校验的完成清单；11 个故障注入场景各重复 200 次，2200 条作用域组件属性中 2199 条成立。最值得注意的是它<strong>以负结果开场</strong>：十个机制都实现了、都在活跃调用路径上可达，却在最后一处连接上失效——&quot;实现、可达、有效&quot;是三个不同问题，第三个需要独立于被测机制的 oracle。作者据此给出两条机械不变量（贝叶斯学习器上的先验距离断言、schema 守卫路径上的 join-liveness 断言），并用三臂消融说明：缺陷存在时改变召回会话命名空间不动后验，缺陷移除后每个实例化臂都动，而&quot;写满工单但不给 engagement&quot;的负对照什么也定不了。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.08253" target="_blank" rel="noreferrer">2608.08253</a></p><blockquote><p>📅 日期：2026-08-08 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 ｜ （第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const g=r(n,[["render",s]]);export{q as __pageData,g as default};
